module alu #(
    parameter ADD = 6'b100000,
    parameter ADDU = 6'b100001,
    parameter SUB = 6'b100010,
    parameter SUBU = 6'b100011,
    parameter AND = 6'b100100,
    parameter OR = 6'b100101,
    parameter XOR = 6'b100110,
    parameter NOR = 6'b100111,
    parameter SLT = 6'b101010,
    parameter SLTU = 6'b101011,
    parameter SLL = 6'b000000,
    parameter SRL = 6'b000010,
    parameter SRA = 6'b000011,
    parameter SLLV = 6'b000100,
    parameter SRLV = 6'b000110,
    parameter SRAV = 6'b000111,
    parameter LUI = 6'b001111
) (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output flag
);

    wire [31:0] a_signed, b_signed;
    assign a_signed = {a[31], a};
    assign b_signed = {b[31], b};

    reg [31:0] res;
    reg [31:0] temp_res;
    reg [31:0] temp_a, temp_b;
    reg [4:0] count;

    always @(*) begin
        case (aluc)
            ADD: begin
                {carry, res} = a_signed + b_signed;
                overflow = carry ^ res[31];
            end
            ADDU: begin
                temp_res = a + b;
                carry = temp_res[32] ^ temp_res[31];
                res = temp_res[31:0];
            end
            SUB: begin
                {carry, res} = a_signed - b_signed;
                overflow = carry ^ res[31];
            end
            SUBU: begin
                temp_res = a - b;
                carry = temp_res[32] ^ temp_res[31];
                res = temp_res[31:0];
            end
            AND: res = a & b;
            OR: res = a | b;
            XOR: res = a ^ b;
            NOR: res = ~(a | b);
            SLT: begin
                temp_res = a_signed < b_signed ? 32'hFFFFFFFF : 32'h00000000;
                res = temp_res;
            end
            SLTU: begin
                temp_res = a < b ? 32'hFFFFFFFF : 32'h00000000;
                res = temp_res;
            end
            SLL: begin
                temp_a = a;
                temp_b = b[5:0];
                for (count = 0; count < temp_b; count = count + 1) begin
                    temp_a = {temp_a[30:0], 1'b0};
                end
                res = temp_a;
            end
            SRL: begin
                temp_a = a;
                temp_b = b[5:0];
                for (count = 0; count < temp_b; count = count + 1) begin
                    temp_a = {1'b0, temp_a[31:1]};
                end
                res = temp_a;
            end
            SRA: begin
                temp_a = a;
                temp_b = b[5:0];
                for (count = 0; count < temp_b; count = count + 1) begin
                    temp_a = {{temp_a[31]}, temp_a[31:1]};
                end
                res = temp_a;
            end
            SLLV: begin
                temp_a = a;
                temp_b = b[5:0];
                for (count = 0; count < temp_b; count = count + 1) begin
                    temp_a = {temp_a[30:0], 1'b0};
                end
                res = temp_a;
            end
            SRLV: begin
                temp_a = a;
                temp_b = b[5:0];
                for (count = 0; count < temp_b; count = count + 1) begin
                    temp_a = {1'b0, temp_a[31:1]};
                end
                res = temp_a;
            end
            SRAV: begin
                temp_a = a;
                temp_b = b[5:0];
                for (count = 0; count < temp_b; count = count + 1) begin
                    temp_a = {{temp_a[31]}, temp_a[31:1]};
                end
                res = temp_a;
            end
            LUI: res = {b, 16'b0};
            default: res = 32'h00000000;
        endcase
    end

    assign r = res;
    assign zero = res == 32'h00000000 ? 1'b1 : 1'b0;
    assign negative = res[31];
    assign flag = aluc == SLT || aluc == SLTU ? 1'b1 : 1'b0;

endmodule
